package com.bank.orderpayments.adapters.out.jdbc;

import com.bank.orderpayments.domain.model.PaymentOrder;
import com.bank.orderpayments.domain.port.OrderRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/** JDBC adapter of the OrderRepository port (table payment_order). */
@Repository
public class JdbcOrderRepository implements OrderRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<PaymentOrder> findByNumberAndCompany(Integer orderNumber, Integer companyId) {
        List<PaymentOrder> rows = jdbcTemplate.query(
                "SELECT order_number, company_id, status, payment_date, commission "
                        + "FROM payment_order WHERE order_number = ? AND company_id = ?",
                (rs, rowNum) -> {
                    Timestamp paymentDate = rs.getTimestamp("payment_date");
                    return new PaymentOrder(
                            rs.getInt("order_number"),
                            rs.getInt("company_id"),
                            rs.getString("status"),
                            paymentDate == null ? null : paymentDate.toLocalDateTime(),
                            rs.getBigDecimal("commission"));
                },
                orderNumber, companyId);
        return rows.stream().findFirst();
    }

    @Override
    public int markPaid(Integer orderNumber, Integer companyId, LocalDateTime paymentDate,
                        java.math.BigDecimal commission) {
        return jdbcTemplate.update(
                "UPDATE payment_order SET status = 'A', payment_date = ?, commission = ? "
                        + "WHERE order_number = ? AND company_id = ?",
                paymentDate == null ? null : Timestamp.valueOf(paymentDate),
                commission,
                orderNumber,
                companyId);
    }
}
